scene.background = new THREE.Color('#10141f');
camera.position.set(4, 3, 6);
controls.target.set(0, 0, 0);

// A soft studio light and a directional key light.
scene.add(new THREE.HemisphereLight('#cbdcff', '#45415d', 2));
const light = new THREE.DirectionalLight('#ffffff', 3);
light.position.set(3, 5, 4);
scene.add(light);

const grid = new THREE.GridHelper(14, 28, '#30374d', '#202738');
grid.position.y = -1.05;
scene.add(grid);

const geometry = new THREE.BoxGeometry(1.6, 1.6, 1.6);
const material = new THREE.MeshStandardMaterial({
  color: '#b49aff', roughness: 0.4, metalness: 0.15
});
const mesh = new THREE.Mesh(geometry, material);
scene.add(mesh);

const useEasing = false;
onFrame(({ elapsed }) => {
  const cycle = (elapsed * 0.4) % 2;
  const t = cycle < 1 ? cycle : 2 - cycle;
  const progress = useEasing ? t * t * (3 - 2 * t) : t;
  mesh.position.x = THREE.MathUtils.lerp(-2, 2, progress);
});

